const handleAddGroupToDay = (dateStr: string, group: { name: string; memberIds: string[]; memberSettings?: { [crewId: string]: { startHour: number; endHour: number; role: string } } }) => {
  setSchedules(current => {
    let updated = [...current];

    group.memberIds.forEach((crewId, idx) => {
      const isAlreadyScheduled = updated.some(s => s.date === dateStr && s.crewId === crewId);
      if (isAlreadyScheduled) return;

      const member = crewMembers.find(c => c.id === crewId);
      const customSetting = group.memberSettings?.[crewId];
      const role = customSetting?.role || member?.role || 'SERVER';

      let startHour = customSetting !== undefined ? customSetting.startHour : 17.0; 
      let endHour = customSetting !== undefined ? customSetting.endHour : 22.0;   

      if (customSetting === undefined) {
        if (role === 'MANAGER') {
          startHour = 17.0;
          endHour = 24.0;
        } else if (role === 'CHEF' || role === 'LINE COOK') {
          startHour = 16.0;
          endHour = 22.0;
        }
      }

      const newId = `group_shift_${dateStr}_${crewId}_${Date.now()}_${idx}`;
      const newItem = {
        id: newId,
        crewId: crewId,
        crewName: member?.name || crewId,
        date: dateStr,
        startHour: startHour,
        endHour: endHour,
        time: formatTimeFrame(startHour, endHour),
        role: role.toUpperCase(),
        location: dropLocation || 'The Chicago Theatre',
        notes: `Added as part of group: ${group.name}`
      };

      updated.push(newItem);
    });

    localStorage.setItem('7h_crew_schedules', JSON.stringify(updated));
    window.dispatchEvent(new Event('storage'));

    fetch("/api/crew/calendar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updated)
    }).catch(err => console.error("Failed to sync schedules:", err));

    return updated;
  });

